def isbn13_valid(s):
    if not isinstance(s, str):
        return False
    t = ''.join(ch for ch in s if ch != ' ' and ch != '-')
    if len(t) != 13:
        return False
    total = 0
    for i, ch in enumerate(t):
        if '0' <= ch <= '9':
            d = ord(ch) - 48
        else:
            return False
        total += d * (1 if i % 2 == 0 else 3)
    return total % 10 == 0
