def parse_ini(text):
    result = {}
    current = None
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if line.startswith(';') or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            name = line[1:-1].strip()
            current = result.setdefault(name, {})
            continue
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()
            if current is None:
                current = result.setdefault('', {})
            current[key] = value
            continue
        raise ValueError(f'Invalid line: {raw_line!r}')
    return result
```

